const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Los Angeles geometry
  const la = ee.Geometry.Point([-118.24, 34.05]).buffer(50000); // 50km radius

  // Define time periods
  const periods = {
    '2018': ['2018-10-01', '2018-10-24'],
    '2019': ['2019-10-01', '2019-10-24'],
    '2021': ['2021-10-01', '2021-10-24']
  };

  const results = {};

  // Process each period
  for (const [year, dates] of Object.entries(periods)) {
    const col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(dates[0], dates[1])
      .filterBounds(la)
      .select('tropospheric_NO2_column_number_density');

    const size = col.size().getInfo();

    if (size === 0) {
      console.log(`No images for ${year}`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Apply quality masking and calculate mean
    const masked = col.map(function(img) {
      const qa = img.select('tropospheric_NO2_column_number_density_validity');
      return img.updateMask(qa.gte(75));
    });

    const mean = masked.mean();

    // Check valid pixel count
    const stats = mean.reduceRegion({
      reducer: ee.Reducer.count().combine({
        reducer2: ee.Reducer.mean(),
        sharedInputs: true
      }),
      geometry: la,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const count = stats['tropospheric_NO2_column_number_density_count'];
    const value = stats['tropospheric_NO2_column_number_density_mean'];

    if (!count || count === 0) {
      console.log(`No valid pixels for ${year}`);
      console.log("<answer>C2</answer>");
      return;
    }

    if (value === null || value === undefined || isNaN(value)) {
      console.log(`Invalid calculation for ${year}`);
      console.log("<answer>C3</answer>");
      return;
    }

    results[year] = { count: count, value: value, size: size };
    console.log(`${year}: Images=${size}, Pixels=${count}, NO2=${(value * 1e6).toFixed(2)} μmol/m²`);
  }

  // Compare 2021 vs 2018 and 2019
  const lower_than_2018 = results['2021'].value < results['2018'].value;
  const lower_than_2019 = results['2021'].value < results['2019'].value;

  if (lower_than_2018 && lower_than_2019) {
    console.log("2021 NO2 was lower than both 2018 and 2019");
    console.log("<answer>A</answer>");
  } else {
    console.log("2021 NO2 was NOT lower than both comparison years");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
